// App-owned "studio" sessions (#3137) — the single source of truth for the fixed pane ids of the
// dedicated, app-launched singleton terminal sessions: the DESIGNER (Design Studio), the LIBRARIAN
// (Algorithms), the ARCHITECT (Teams), and the SOUND-DESIGNER (Sounds). Each is a singleton session the app owns and re-creates on
// demand — NOT a fleet worker and NOT something the user restores. Since #3357 all three (like the DEBUG
// session, #3326) run on the shared TerminalHost via `@/features/studio-sessions`, not on their own page-owned
// xterm; their ids stay fixed here so the lifecycle, the Glance morph, and recovery all agree.
//
// Their ids follow the `<key>:<tail>` grammar, so `parsePaneIdentity` would otherwise classify them as
// fleet WORKERS and the crash-recovery banner would offer to restore them (#3137). This module names
// them in ONE feature-agnostic place so both the feature hooks (which import their `*_PANE_ID` from here)
// and the recovery reconcile (`reconcileSessions`, which excludes them) agree — a new studio added here
// is excluded everywhere at once. The PLANNER is the sibling app-owned session, but it has a DYNAMIC
// per-project id (`planning_<key>`) and its own `isPlanningPaneId` guard, so it isn't listed here.

/** The Design Studio's app-owned designer session, one per kit technology. */
export const designerSessionId = (tech: string): string => `design-studio:designer-${tech}`;

/** The Algorithms studio's app-owned librarian session, one per technology.
 *
 *  A HYPHEN, never a second colon: the pane-id grammar is `<key>:<tail>` and several call sites read
 *  the project key as `paneId.split(":")[0]`. A second colon would not break that read, but it changes
 *  what the TAIL means for anything that splits further — so the tech rides in the tail. */
export const librarianSessionId = (tech: string): string => `algorithms-studio:librarian-${tech}`;

/**
 * The TECHNOLOGY AXIS — which technologies actually have something to curate right now
 * (`the-studio-session-set-is-derived-not-declared`).
 *
 * THIS USED TO BE TWO DECLARED LISTS, and the declaration was the bug. `LIBRARIAN_TECHS` read
 * `["rust", "typescript", "python"]` and its own doc explained that a fourth technology "needs a
 * fourth entry here". Nobody ever removed the third: MEASURED 2026-09-09 over the committed record
 * store, `impl.tech` is `{rust: 1944, typescript: 79}` and there is no python record anywhere in this
 * repo — so `librarianPython` was a session for a technology with nothing in it, offered by
 * `bsc session list`, startable by `bsc session start`, drawn as a Glance node, and typed into every
 * store map. That inverts the rule the whole app is built on: if a thing exists there must be a way to
 * maintain it, and the converse — do not offer to maintain nothing.
 *
 * So the axis is READ FROM THE STORES that already answer it, and the session set is a projection
 * over it. The librarian axis is the algorithms graph's own `kitTechs(graph)` — "the techs that carry
 * at least one implementation" — and the designer axis is the `tech` on the kits the component store
 * holds. Neither is restated here, which is the point: a python record landing mints `librarianPython`
 * with no code change, and its absence un-mints it just as automatically.
 *
 * # Why this is not a hole in the closed set
 *
 * `bsc session`'s argument space is closed because every id it accepts is one the app OWNS, and that
 * survives intact: what is compiled is the set of studio KINDS (designer · librarian · architect ·
 * sound-designer · integrator), each carrying the things only code can carry — a Tauri setup-command
 * name, a persona id, a role gate, a workspace page. The technology is only ever a validated TAIL on
 * a compiled kind, exactly as a network's slug is in `network_architect_slug` and a surface's noun is
 * in `surface_session_kind`. And the derived axis makes the set strictly NARROWER than the declared
 * one it replaces, never wider.
 */
export interface StudioAxis {
  /** The techs the ALGORITHMS graph actually holds (`impl.tech`) — one librarian each. */
  readonly librarian: readonly string[];
  /** The techs the component store's KITS actually declare (`kit.tech`) — one designer each. The
   *  component store partitions one level up from the algorithms graph, which is why this is a second
   *  list rather than the same one read twice. */
  readonly designer: readonly string[];
}

/** The axis before anything has been read — no technology has anything to curate, so no per-technology
 *  studio exists yet. Deliberately EMPTY rather than a guess: a placeholder roster would be the
 *  declared list again, under a new name, and would offer a session for a technology nobody has
 *  checked for. The two single-technology studios (architect · sound-designer · integrator) are
 *  unaffected — they carry no axis at all and are always present. */
export const EMPTY_STUDIO_AXIS: StudioAxis = { librarian: [], designer: [] };

/** A technology is a pane-id TAIL and a directory-safe name, so it is VALIDATED rather than accepted —
 *  the same rule `network_slug_with_tail` applies for the same reason. Lowercase, digits and hyphens
 *  only: anything else would reach a pane key or a path as something other than a name. */
export function isStudioTech(tech: string): boolean {
  return tech.length > 0 && /^[a-z0-9-]+$/.test(tech);
}

/** The axis with every technology that cannot be a pane tail dropped, deduped, in the store's own
 *  order. Every projection goes through this, so a malformed `tech` on one record cannot mint a
 *  session — it is simply not one of the technologies that has a curator. */
export function studioAxis(librarian: readonly string[], designer: readonly string[]): StudioAxis {
  const clean = (xs: readonly string[]) => [...new Set(xs.filter(isStudioTech))];
  return { librarian: clean(librarian), designer: clean(designer) };
}

/** The two studios whose store is partitioned, as a GRAMMAR over their pane ids.
 *
 *  A grammar rather than a membership test, and that difference is load-bearing: `studioRoleForPaneId`
 *  is read by the LAUNCH to decide a session's confinement, and a membership test against a roster
 *  returns null for anything not in it. A null role means no role gate, no denies and no
 *  `restrictedAllow` — the fully unconfined shell `studioRoleForPaneId` was itself added to prevent.
 *  With a derived roster that failure would arrive the moment a technology appeared before the axis
 *  was read. A grammar cannot have that failure: `algorithms-studio:librarian-<anything>` is a
 *  librarian pane whether or not anything has told this module which technologies exist. */
export const PER_TECH_STUDIO_PANES = [
  { kind: "designer" as const, prefix: "design-studio:designer-" },
  { kind: "librarian" as const, prefix: "algorithms-studio:librarian-" },
];

/** The kind and technology a per-technology studio pane names, or null for any other pane. */
export function studioPaneTech(paneId: string): { kind: "designer" | "librarian"; tech: string } | null {
  for (const { kind, prefix } of PER_TECH_STUDIO_PANES) {
    if (!paneId.startsWith(prefix)) continue;
    const tech = paneId.slice(prefix.length);
    return isStudioTech(tech) ? { kind, tech } : null;
  }
  return null;
}
/** The Teams studio's app-owned architect session. */
export const TEAMS_STUDIO_SESSION_ID = "teams-studio:architect";
/** The Sound studio's app-owned sound-designer session (#3369, epic #3071 phase 4). */
export const SOUND_STUDIO_SESSION_ID = "sound-studio:sound-designer";
/** The Integration studio's app-owned integrator session (#4023) — builds and maintains the app's
 *  integrations with existing applications/APIs through `bsc data connector`. */
export const INTEGRATION_STUDIO_SESSION_ID = "integration-studio:integrator";
/** The Debug studio's app-owned debugger session (#3298) — a full-capability session in the
 *  base-studio-code SOURCE tree that works the `bsc request` improvement queue (fixing `bsc ui`),
 *  hosted in its own OS window and toggled from Settings. */
export const DEBUG_STUDIO_SESSION_ID = "debug-studio:debugger";

/** The pane-id prefix shared by EVERY session in the debug studio: the standing debugger
 *  (`debug-studio:debugger`) and each auto-spawned per-request session (`debug-studio:req-<id>`,
 *  {@link poolPaneId}). Every one of them is the app's full-capability maintenance session in the
 *  source tree, so the prefix — not the singleton id — is what `isFullCapabilitySession` keys on. */
export const DEBUG_STUDIO_PANE_PREFIX = "debug-studio:";

/** The pane-id prefix shared by every SURFACE session (`a-noun-and-its-verbs-launch-their-personas`):
 *  the operator on a noun (`surface-studio:noun-<noun>`) and the maintainer on a verb
 *  (`surface-studio:verb-<noun>-<verb>`). Declared here, beside the other pane-id predicates, rather
 *  than only in the Glance feature that mints them — {@link surfaceRoleForPaneId} is read by the
 *  LAUNCH, which must not import a feature to find out what it is confining. */
export const SURFACE_STUDIO_PANE_PREFIX = "surface-studio:";

/** The prefix of an OPERATOR's pane — the persona that drives one `bsc <noun>`. */
const SURFACE_OPERATOR_PREFIX = `${SURFACE_STUDIO_PANE_PREFIX}noun-`;

/**
 * The confined role a SURFACE session's pane id resolves to, or `null` for any other pane.
 *
 * THIS IS THE FIX FOR A FULLY UNCONFINED SHELL. A surface session is registered by
 * `openSurfaceSession`, which sets the pane's model, provider and charter and no ROLE — so
 * `paneRole` fell through to `studioRoleForPaneId`, which knows only the FIXED studio registry, and
 * landed on `undefined`. A missing role means no role gate, no denies and no `restrictedAllow`: the
 * whole `base.json` baseline, whose build tier carries `cargo`. MEASURED 2026-09-03 — the studio
 * operator ran `cd <repo> && cargo run --bin bsc -- studio list`, compiling in the tree the running
 * app owns, to invoke a binary already on its PATH.
 *
 * That is the SAME failure `studioRoleForPaneId` was added to fix, and the same remedy: confinement
 * travels with the session's stable identity rather than with setup order, so a pane cannot reach the
 * launch unconfined because some registration step had not run yet.
 *
 * Deliberately null for a MAINTAINER (`verb-`) pane: that persona edits its crate and legitimately
 * holds the build tier. Confining it is a separate decision about a different actor, not a detail of
 * this one — and returning a confined role here would silently take `cargo` from the one surface
 * session that needs it.
 */
export function surfaceRoleForPaneId(paneId: string): "operator" | null {
  return paneId.startsWith(SURFACE_OPERATOR_PREFIX) ? "operator" : null;
}

/** The app-owned studio pane ids that are FIXED — the studios with no technology axis, plus the
 *  standing debug session. The per-technology studios are deliberately absent: their pane ids are
 *  derived from the axis, so they are recognised by {@link studioPaneTech}'s grammar rather than
 *  enumerated here. A list that tried to hold them would be the declared roster again. */
export const SINGLE_STUDIO_PANE_IDS: readonly string[] = [
  TEAMS_STUDIO_SESSION_ID,
  SOUND_STUDIO_SESSION_ID,
  INTEGRATION_STUDIO_SESSION_ID,
  DEBUG_STUDIO_SESSION_ID,
];

/** Whether `id` is an app-owned studio session pane (designer / librarian / architect / sound-designer /
 *  integrator / debugger) — excluded from crash recovery the way the planner (`isPlanningPaneId`) is:
 *  re-created when its workspace opens, never restored from the recovery banner.
 *
 *  GRAMMAR-then-list, not a single list, since `the-studio-session-set-is-derived-not-declared`. The
 *  answer must not depend on the axis having been read: a designer pane that this predicate failed to
 *  recognise would be offered by the crash-recovery banner as if it were a fleet worker, and would
 *  reach the launch with no role gate. Recognising the SHAPE is always safe — every
 *  `algorithms-studio:librarian-<tech>` is a librarian pane whether or not that technology currently
 *  has records — whereas recognising only the derived set is safe only after the derivation has run. */
export function isStudioSessionPaneId(id: string): boolean {
  return studioPaneTech(id) !== null || SINGLE_STUDIO_PANE_IDS.includes(id);
}

/** Whether `id` is a FULL-CAPABILITY app-owned session that must ALWAYS launch bypass + role-less,
 *  regardless of the global permission posture (`bypassPermissions`) — ANY session in the debug studio
 *  (#3326/#3520). Unlike a fleet/console pane, whose posture comes from the store (role/profile/flow + the
 *  global bypass toggle), a debug-studio session is BY DEFINITION the unrestricted maintenance session in
 *  the base-studio-code source tree; `buildSessionSettings` forces `bypass:true` for it. Role-less is
 *  automatic — no `paneRoles` entry is set for these panes and `studioRoleForPaneId` matches only the four
 *  fixed studios, so no role gate applies.
 *
 *  Matches the whole `debug-studio:` family, not just the singleton (#3520): the standing debugger AND each
 *  auto-spawned per-request session (`debug-studio:req-<id>`, #3498). A req session is the same kind of
 *  actor as the standing one — app-owned, in the source tree, working the request queue — and the control
 *  gate is the human reviewing its PR, not a per-tool permission prompt. Keying on the singleton id left
 *  the spawned sessions falling through to the global toggle, so they stopped to ask for every edit. */
export function isFullCapabilitySession(id: string): boolean {
  return id.startsWith(DEBUG_STUDIO_PANE_PREFIX);
}

