// App-owned studio sessions (#3137) — the recovery-exclusion source of truth.
import { describe, it, expect } from "vitest";
import {
  isStudioSessionPaneId,
  surfaceRoleForPaneId,
  SURFACE_STUDIO_PANE_PREFIX,
  isFullCapabilitySession,
  SINGLE_STUDIO_PANE_IDS,
  studioPaneTech,
  designerSessionId,
  librarianSessionId,
  TEAMS_STUDIO_SESSION_ID,
  DEBUG_STUDIO_SESSION_ID,
} from "@/shared/lib/session/systemSessions";

describe("isStudioSessionPaneId (#3137)", () => {
  it("matches each app-owned studio session id", () => {
    for (const id of [designerSessionId("react"), librarianSessionId("rust"), TEAMS_STUDIO_SESSION_ID, DEBUG_STUDIO_SESSION_ID]) {
      expect(isStudioSessionPaneId(id)).toBe(true);
    }
    // #system-sessions-are-per-technology: the pane ids are per-tech, and the TAIL carries the
    // technology after a HYPHEN — a second colon would change what anything splitting the tail sees.
    // Recognised by GRAMMAR since `the-studio-session-set-is-derived-not-declared`, so the assertion
    // is about the SHAPE rather than about membership of a list that can no longer hold them all.
    expect(studioPaneTech("design-studio:designer-react")).toEqual({ kind: "designer", tech: "react" });
    expect(studioPaneTech("algorithms-studio:librarian-rust")).toEqual({ kind: "librarian", tech: "rust" });
    expect(studioPaneTech("design-studio:designer-react-native")?.tech).toBe("react-native");
    for (const id of [...SINGLE_STUDIO_PANE_IDS, "design-studio:designer-react", "algorithms-studio:librarian-rust"]) {
      expect(id.split(":"), `${id} keeps the <key>:<tail> grammar`).toHaveLength(2);
    }
    expect(SINGLE_STUDIO_PANE_IDS).toContain("teams-studio:architect");
    expect(SINGLE_STUDIO_PANE_IDS).toContain("debug-studio:debugger");
  });

  it("does NOT match real fleet / manual / planner ids (they share the `<key>:<tail>` shape)", () => {
    for (const id of ["proj:auth", "proj:director", "own/web:triage", "man:scratch:p0", "planning_proj", "garbage"]) {
      expect(isStudioSessionPaneId(id)).toBe(false);
    }
  });

  it("lists exactly the studios no grammar describes — the rest are recognised by shape", () => {
    // The per-technology ids are GONE from this list, and that is the change
    // (`the-studio-session-set-is-derived-not-declared`). They were nine literals including
    // `algorithms-studio:librarian-python`, a pane for a technology with no record anywhere in the
    // repo — and being in this list is what made it recovery-excluded, i.e. treated as a real
    // app-owned session. What is left is the ids that genuinely have no grammar: the
    // single-technology studios and the STANDING debugger, which must be named rather than matched
    // because `debug-studio:req-<n>` shares its prefix and resumes nothing.
    expect([...SINGLE_STUDIO_PANE_IDS].sort()).toEqual(
      ["debug-studio:debugger", "integration-studio:integrator",
       "sound-studio:sound-designer", "teams-studio:architect"],
    );
    // ...and the ones it dropped are still recognised, including a technology nothing has ever held.
    for (const id of ["algorithms-studio:librarian-rust", "algorithms-studio:librarian-typescript",
                      "design-studio:designer-react", "design-studio:designer-react-native",
                      "algorithms-studio:librarian-python"]) {
      expect(isStudioSessionPaneId(id), `${id} is still an app-owned studio pane`).toBe(true);
    }
  });
});

describe("isFullCapabilitySession (#3326)", () => {
  it("is true for the standing debug session — the always-bypass carve-out", () => {
    expect(isFullCapabilitySession(DEBUG_STUDIO_SESSION_ID)).toBe(true);
  });

  it("is true for EVERY auto-spawned per-request debug session (#3520)", () => {
    // A `debug-studio:req-<id>` session is the same full-capability actor as the standing one — app-owned,
    // in the source tree, working the request queue. It must launch bypass too, or it stops to ask for
    // every edit; the control gate is the human reviewing its PR, not a per-tool prompt.
    for (const id of ["debug-studio:req-1", "debug-studio:req-7", "debug-studio:req-142"]) {
      expect(isFullCapabilitySession(id)).toBe(true);
    }
  });

  it("is false for the other studios (they keep their bespoke launch postures)", () => {
    for (const id of [designerSessionId("react"), librarianSessionId("rust"), TEAMS_STUDIO_SESSION_ID]) {
      expect(isFullCapabilitySession(id)).toBe(false);
    }
  });

  it("is false for fleet / manual / planner ids (they follow the global posture)", () => {
    // Including a `debug-studio`-ish decoy that is NOT the prefix — the match is on `debug-studio:`, so a
    // pane merely CONTAINING the word must not slip through.
    for (const id of ["proj:auth", "proj:director", "own/web:triage", "man:scratch:p0", "planning_proj", "my-debug-studio:x"]) {
      expect(isFullCapabilitySession(id)).toBe(false);
    }
  });
});

// ── the surface sessions' confinement (`surface-operator-runs-confined-to-its-own-noun`) ───────────
//
// THE REGRESSION: `openSurfaceSession` sets a surface pane's model, provider and charter and never its
// ROLE, and a surface pane is not in the fixed studio registry — so `paneRole` landed on `undefined`,
// which means no role gate, no denies and no `restrictedAllow`: the whole `base.json` baseline, build
// tier included. MEASURED — the studio operator ran `cargo run --bin bsc -- studio list`, compiling in
// the tree the running app owns, to invoke a binary already on its PATH.
describe("surfaceRoleForPaneId (`surface-operator-runs-confined-to-its-own-noun`)", () => {
  it("resolves an OPERATOR's pane to a confined role, from the pane id alone", () => {
    expect(surfaceRoleForPaneId("surface-studio:noun-studio")).toBe("operator");
    expect(surfaceRoleForPaneId("surface-studio:noun-persona")).toBe("operator");
    // From the id ALONE is the whole point: no store entry, no registration step, nothing that can
    // not-have-run-yet. That is why this is a pure function of the string.
    expect(surfaceRoleForPaneId(`${SURFACE_STUDIO_PANE_PREFIX}noun-anything-at-all`)).toBe("operator");
  });

  it("leaves a MAINTAINER's pane alone — it edits its crate and keeps the build tier", () => {
    expect(surfaceRoleForPaneId("surface-studio:verb-logs-summary")).toBeNull();
  });

  it("claims no pane that is not a surface session", () => {
    for (const id of [
      "design-studio:designer-react",
      "debug-studio:req-96",
      "proj:director",
      "proj:auth",
      "surface-studioX:noun-studio",
      "",
    ]) {
      expect(surfaceRoleForPaneId(id)).toBeNull();
    }
  });

  // A surface pane is NOT a fixed studio: the two predicates answer different questions and must not
  // be conflated, or recovery would start offering to restore a surface session.
  it("is disjoint from the fixed studio registry", () => {
    expect(isStudioSessionPaneId("surface-studio:noun-studio")).toBe(false);
    expect(surfaceRoleForPaneId("design-studio:designer-react")).toBeNull();
  });
});
